import './App.css';
import * as React from 'react';

import { useState, useEffect } from 'react';

// for the calendar date selection
import dayjs from 'dayjs';

// components
import NavigationBar from './components/NavigationBar';
import ActionBar from './components/ActionBar';
import ItemGrid from './components/ItemGrid';
import LoginPage from './components/LoginPage';
import { MessageProvider, useMessage } from './components/MessageContext';
import MessageScreen from './components/MessageScreen';


// convert a datetime object from the server to a more readable format for the frontend.
const formatDate = (dateStr) => {
  const d = new Date(dateStr);

  return d.toLocaleDateString("en-US", {
    timeZone: "UTC",
    weekday: "long",
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};

const AppContent = () => {
	// site title passed into various components.
	const siteTitle = "Daily Journal App"

	// urls passed into various states and functions.
	let local_url = 'http://localhost:5000/api';
	let python_anywhere_url = 'https://blakehoff.pythonanywhere.com/api';
	let url_list = [
		{"local5000": local_url},
		{"pyAnywhere": python_anywhere_url}
	];

	const [server_url, set_server_url] = useState(python_anywhere_url);
	const [userID, setUserID] = useState(null);
	const [usersName, setUsersName] = useState(null);
    const [gridData, setGridData] = useState([]); // array of {id, type_id, name, icon, date, created_at, description}
	const [filteredData, setFilteredData] = useState([]);
	
	const [filteredTypes, setFilteredTypes] = useState([]); // array of [typeName ...]
	const [typeData, setTypeData] = useState([]); // array of {name, created_at} (use [id-1] to access a particular id; ids start at 1)
	
	// ----- ActionBar Fields -----
	const [selectedType, setSelectedType] = useState('');
	const [selectedID, setSelectedID] = useState(-1); // stores the ID that will be used for editing
	const [entryValue, setEntryValue] = useState('');
	const [entryName, setEntryName] = useState('');
	
	// selected date (default = today)
	const [selectedDate, setSelectedDate] = useState(dayjs());
	const [loggedIn, setLoggedIn] = useState(-1); // set to -1 so neither loginpage or the user page is displayed until the server responds
	
	const { showMessage } = useMessage();

	// filtering the grid
	useEffect(() => {
		const filteredResults = gridData.filter(item => { // looking at all items in the grid, do some tests, 
			try{
				const getGridItemType = typeData[item.type_id-1]; 

				return filteredTypes.includes(getGridItemType);
			}catch{
				return false;
			}
		});

		setFilteredData(filteredResults);
		
	}, [gridData, filteredTypes, typeData]);

	const clearActionBar = () => {
		// fields to reset are: ID, entryValue, entryName
		setSelectedID(-1);
		setEntryValue('');
		setEntryName('');
		setSelectedDate(dayjs());
	};

	// populating the grid
	const getGridData = React.useCallback(async () => {
		let url = `${server_url}/view/`;
		const token = localStorage.getItem("authToken");

		try {
			const response = await fetch(url, {
				method: "GET",
				headers: {
					"Authorization": `Bearer ${token}`
				}
			}
			);

			const responseData = await response.json();
			console.log(responseData.items);
			console.log('GET (Items)')

			setGridData(responseData.items);
			return {"responseData": responseData, "response": response};
		} 
		catch (err) {
			console.log("Something went wrong!", err);
			return {"error": err};

		}
	}, [server_url]);

	// populating the type data dropdown/filter
	const getTypeData = React.useCallback(async () => {
		let url = `${server_url}/types/`;
		const token = localStorage.getItem("authToken");

		try {
			const response = await fetch(url, {
				method: "GET",
				headers: {
					"Authorization": `Bearer ${token}`
				}}
			);

			const data = await response.json();
			console.log(data.items);
			console.log('GET (Types)')

			setTypeData(data.items);
			setFilteredTypes(data.items);
			setSelectedType(data.items[0]);
		} 
		catch (err) {
			console.log("Something went wrong!", err);
		}
	}, [server_url]);

	const handleGetAll = React.useCallback(async () => {
		try {
			let gridResults = await getGridData();
			let typeResults = await getTypeData();
			console.log("get all");
			console.log(gridResults);
			console.log(typeResults);
		}
		catch (err) {
			console.error(err);
		}
	}, [getGridData, getTypeData, showMessage]);

	// determine if the user has a session
	const checkLogin = React.useCallback(async () => {
		let url = `${server_url}/auth/user/`;
		const token = localStorage.getItem("authToken");
		
		// only make the request if the token exists.
		if(token){
			const response = await fetch(url, {
				method: "GET",
				headers: {
					"Authorization": `Bearer ${token}`
				}}
			);
			const data = await response.json();

			if(data.logged_in){
				setLoggedIn(1);
				handleGetAll();
				setUserID(data.id);
				setUsersName(data.username)
				console.log("User is Logged In");
				return;
			}
		}
		// reach here if the token does not exist 
		// or the user is not logged in

		setLoggedIn(0);
		localStorage.removeItem("authToken");
		setUserID(null);
		console.log("Not logged in");
	}, [handleGetAll, server_url]);

	const handleSetID = React.useCallback(async (item_id, item_date, item_type, item_name, item_desc) => {
		try {
			if(selectedID === item_id){
				clearActionBar();
			}
			else{
				setSelectedID(item_id);
				const stringDate = new Date(item_date).toISOString().split("T")[0];
				setSelectedDate(dayjs(stringDate)); // the calendar component needs the date to be in datejs format
				setSelectedType(item_type);
				setEntryName(item_name); // can use the grid data since i have the id already.
				setEntryValue(item_desc);
			}
		}
		catch (err) {
			console.error(err);
		}
	}, [selectedID]);

	const handleEditItem = React.useCallback(async () => {
		let url = `${server_url}/update/${selectedID}`;
		const token = localStorage.getItem("authToken");

		const payload = {
			description: entryValue,
			date: selectedDate.format('YYYY-MM-DD'),
			type_name: selectedType,
			entry_name: entryName
			};
			try {
				// send the value in the text field to the server
				const response = await fetch(url, {
					method: 'POST',
					headers: {
						"Authorization": `Bearer ${token}`,
						'Content-Type': 'application/json', // Tells server to expect JSON
						'Accept': 'application/json'        // Tells server client expects JSON back
					},
					body: JSON.stringify(payload)          // Converts object into a valid JSON string
				});

				const responseData = await response.json(); // Parses returning JSON string to object
				if (!response.ok) {
					// throw new Error(`HTTP error! Status: ${response.status}`);
					showMessage(
						responseData.message,
						`Invalid (${response.status})`,
						'error'
					);
				}

				console.log('Success:', responseData);
				showMessage(responseData.message);
			}
			catch (err) {
				console.error("Something went wrong!", err);
				showMessage(`Error editing entry with ID (${selectedID}).`, err.message,'error');
				return null;
			}

			handleGetAll(); // retrieve the updated grid after successful edit.
			clearActionBar();
	}, [handleGetAll, server_url, entryName, selectedID, entryValue, selectedDate, selectedType, showMessage]);

	const handleDeleteItem = React.useCallback(async (id) => {
			let url = `${server_url}/item/${id}`;
			console.log(url)
			const token = localStorage.getItem("authToken");

			try{
				const response = await fetch(url, {
					method: "DELETE", 
					headers: {
						"Authorization": `Bearer ${token}`
					}}
				);
				const responseData = await response.json();

				console.log(responseData)
				if(!response.ok){
					showMessage(
						responseData.message,
						`Invalid (${response.status})`,
						'error'
					);
				}
				showMessage(responseData.message);
				
				handleGetAll(); // retrieve the updated grid after deletion.
				clearActionBar();
			}
			catch(err) {
				console.error("Something went wrong!", err);
				showMessage(`Error deleting entry with ID (${id}).`, err.message,'error');
			}

	}, [handleGetAll, server_url, showMessage]);

	const createEntry = async (entryValue, selectedDate, selectedType, selectedName) => {
		let url = `${server_url}/create/`;
		const token = localStorage.getItem("authToken");

		const payload = {
			description: entryValue,
			date: selectedDate.format('YYYY-MM-DD'), // format the date in a simple string for the server.
			type_name: selectedType,
			entry_name: selectedName
		};
		try {
			// send the value in the text field to the server
			const response = await fetch(url, {
				method: 'POST',
				headers: {
					"Authorization": `Bearer ${token}`,
					'Content-Type': 'application/json', // Tells server to expect JSON
					'Accept': 'application/json'        // Tells server client expects JSON back
				},
				body: JSON.stringify(payload)          // Converts object into a valid JSON string
			});
			
			const responseData = await response.json(); // Parses returning JSON string to object

			if (!response.ok) {
				showMessage(
					responseData.message,
					`Invalid (${response.status})`,
					'error'
				);
				throw new Error(`HTTP error! Status: ${response.status}`);
			}

			console.log('Success:', responseData);
			showMessage(responseData.message);

			handleGetAll();
			clearActionBar();
		} 
		catch (err) {
			console.error(err);
			showMessage(`Error creating entry with description (${entryValue}).`, err.message,'error');
		}
	};

	const handleSignUp = async (username, email, password) => {
		let url = `${server_url}/auth/signup/`;

		console.log(username, email, password)

		const payload = {
			username: username,
			email: email,
			password: password,
		};
		try {
			const response = await fetch(url, {
				method: 'POST',
				headers: {
					'Content-Type': 'application/json', // Tells server to expect JSON
					'Accept': 'application/json'        // Tells server client expects JSON back
				},
				body: JSON.stringify(payload)          // Converts object into a valid JSON string
			});

			if (!response.ok) {
				const responseData = await response.json();
				
				showMessage(
					responseData.message,
					`Invalid (${response.status})`,
					'error'
				);

				throw new Error(`HTTP error! Status: ${response.status} Message: ${responseData.message}`);
			}

			const responseData = await response.json(); // Parses returning JSON string to object
			console.log('Success:', responseData);
			if(response.status === 200){
				showMessage(
					responseData.message,
					`Successfully created account "${username}"! (${response.status})`,
					'success'
				);
			}
			else{
				showMessage(
					responseData.message,
					`Could not create account. (${response.status})`,
					'error'
				);
			}
		} 
		catch (err) {
			console.error(err);
			showMessage(`Error signing up with account named ${username}.`, err.message,'error');
		}
	};

	const handleLogin = async (username, password) => {
		let url = `${server_url}/auth/login/`;

		console.log(username, password)

		const payload = {
			username: username,
			password: password
		};
		try {
			const response = await fetch(url, {
				method: 'POST',
				headers: {
					'Content-Type': 'application/json', // Tells server to expect JSON
					'Accept': 'application/json'        // Tells server client expects JSON back
				},
				body: JSON.stringify(payload)          // Converts object into a valid JSON string
			});

			if (!response.ok) {
				const responseData = await response.json();
				
				showMessage(
					responseData.message,
					`Invalid (${response.status})`,
					'error'
				);

				throw new Error(`HTTP error! Status: ${response.status} Message: ${responseData.message}`);
			}

			const responseData = await response.json();
			console.log('Success:', responseData);
			localStorage.setItem("authToken", responseData.token);
			checkLogin();
			showMessage(
				responseData.message,
				`Logged in successfully! (${response.status})`,
				'success'
			);
		} 
		catch (err) {
			console.error(err);
			showMessage(`Error logging in to account named ${username}.`, err.message,'error');
		}
	};

	const handleLogout = React.useCallback(async () => {
		let url = `${server_url}/auth/logout/`;
		console.log(url);
		const token = localStorage.getItem("authToken");

		try {
			const response = await fetch(url, {
				method: 'POST',
				headers: {
					"Authorization": `Bearer ${token}`,
					'Content-Type': 'application/json', // Tells server to expect JSON
					'Accept': 'application/json'        // Tells server client expects JSON back
				}}
			);

			
			const responseData = await response.json(); // Parses returning JSON string to object
			console.log('Success:', responseData);
			setLoggedIn(0);
			localStorage.removeItem("authToken");
			setUserID(null);
			setUsersName(null);
			if (!response.ok) {
				showMessage(
					responseData.message,
					`Server not found. Still logged out successfully! (${response.status})`,
					'success'
				);
				throw new Error(`HTTP error! Status: ${response.status} Message: ${responseData.message}`);
			}
			showMessage(
				responseData.message,
				`Logged out successfully! (${response.status})`,
				'success'
			);
		}
		catch (err) {
			console.error(err);
		}
	}, [server_url, showMessage]);

	// check if user has login credentials already
	useEffect(() => {checkLogin();},[checkLogin, server_url]); 
  return (
		<div className="App">
			<MessageScreen />
			
			<NavigationBar 
				title={siteTitle}
				loggedIn={loggedIn}
				handleLogout={handleLogout}
				server_url={server_url}
				set_server_url={set_server_url}
				url_list={url_list}
				usersName={usersName}
			/>

			{loggedIn === 0 &&
				<LoginPage 
					title={siteTitle} 
					handleSignUp={handleSignUp} 
					handleLogin={handleLogin}
				/>
			}

			{loggedIn === 1 && <div>
				<ActionBar 
					handleGetAll={handleGetAll}
					selectedDate={selectedDate}
					setSelectedDate={setSelectedDate}
					createEntry={createEntry}
					gridData={gridData}
					entryValue={entryValue}
					setEntryValue={setEntryValue}
					entryName={entryName}
					setEntryName={setEntryName}
					typeData={typeData}
					selectedType={selectedType}
					setSelectedType={setSelectedType}
					filteredTypes={filteredTypes}
					setFilteredTypes={setFilteredTypes}
				/>

				<ItemGrid
					filteredData={filteredData}
					formatDate={formatDate}
					handleDeleteItem={handleDeleteItem}
					typeData={typeData}
					selectedID={selectedID}
					handleSetID={handleSetID}
					handleEditItem={handleEditItem}
				/>
			</div>
			}
			
		</div>
  );
};

const App = () => {
	return (
		<MessageProvider>
			<AppContent/>
		</MessageProvider>
	);
}

export default App;
